CREATE TABLE IF NOT EXISTS kinnect_core.privacy_consents(user_id text PRIMARY KEY REFERENCES kinnect_core.users(id),version text NOT NULL,created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS kinnect_core.store_preferences(user_id text PRIMARY KEY REFERENCES kinnect_core.users(id),style text NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS kinnect_core.admin_package_events(user_id text NOT NULL REFERENCES kinnect_core.users(id),request_id text NOT NULL,product_id text NOT NULL,created bigint NOT NULL,PRIMARY KEY(user_id,request_id));
CREATE TABLE IF NOT EXISTS kinnect_core.store_purchases(token_hash text PRIMARY KEY,user_id text NOT NULL REFERENCES kinnect_core.users(id),product_id text NOT NULL,token_cipher text NOT NULL,state text NOT NULL,verified bigint NOT NULL,created bigint NOT NULL);
CREATE TABLE IF NOT EXISTS kinnect_core.notifications(id text PRIMARY KEY,user_id text NOT NULL REFERENCES kinnect_core.users(id),actor text,kind text NOT NULL,ref text NOT NULL,seen integer NOT NULL DEFAULT 0,created bigint NOT NULL);
CREATE INDEX IF NOT EXISTS core_notification_user ON kinnect_core.notifications(user_id,created);
CREATE TABLE IF NOT EXISTS kinnect_core.follows(actor text NOT NULL REFERENCES kinnect_core.users(id),target text NOT NULL REFERENCES kinnect_core.users(id),PRIMARY KEY(actor,target));
CREATE TABLE IF NOT EXISTS kinnect_core.economy_audit(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,actor text NOT NULL,version bigint NOT NULL,before_json text NOT NULL,after_json text NOT NULL,created bigint NOT NULL);
ALTER TABLE kinnect_core.privacy_consents ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.store_preferences ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.admin_package_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.store_purchases ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.notifications ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.follows ENABLE ROW LEVEL SECURITY;
ALTER TABLE kinnect_core.economy_audit ENABLE ROW LEVEL SECURITY;
-- Backend role only. Data API is disabled; no anon/authenticated privileges.
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA kinnect_core TO kinnect_api;
GRANT USAGE,SELECT ON ALL SEQUENCES IN SCHEMA kinnect_core TO kinnect_api;
DO $$ DECLARE tab record; BEGIN FOR tab IN SELECT tablename FROM pg_tables WHERE schemaname='kinnect_core' LOOP
 IF NOT EXISTS(SELECT 1 FROM pg_policies WHERE schemaname='kinnect_core' AND tablename=tab.tablename AND policyname='backend_runtime') THEN
 EXECUTE format('CREATE POLICY backend_runtime ON kinnect_core.%I FOR ALL TO kinnect_api USING(true) WITH CHECK(true)',tab.tablename);
 END IF; END LOOP; END $$;
